import json,re
from pathlib import Path
from html.parser import HTMLParser
from collections import Counter
class Text(HTMLParser):
 def __init__(self):super().__init__();self.parts=[]
 def handle_data(self,d):self.parts.append(d)
def plain(x):
 p=Text();p.feed(x);return ''.join(p.parts)
s=json.load(open('source.json'));a=json.load(open('answer.json'));r=json.load(open('reference-targets.json'))
assert len(a)==len(s)==24
kinds={'tax_removed','tax_reduced','obligation_removed','obligation_merged','authorization_removed','regime_merged','deadline_reduced','compliance_cost_reduced','tax_increased','obligation_added','deadline_increased','complexity_added','financing_transfer','payment_deferred','relief_extended','relief_preserved','coordination'}
units={'percent','euro','legal_duty','regime','calendar_days','working_days','financing','other'}
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
class Markup(HTMLParser):
 def handle_starttag(self,t,attrs):
  assert t in allowed,t
  assert all(k in ['rowspan','colspan'] and v.isdigit() for k,v in attrs),attrs
for x,y in zip(s,a):
 for k in ['code_id','source_id','source_sha256','number']:assert x[k]==y[k],(y['number'],k)
 assert y['reason'] and y['review_notes']
 imp=y['substantive_impact'];assert imp['version']==1
 for f in ['assessment','scope_limitations','new_burdens_review']:assert len(imp[f])>=40,(x['number'],f)
 if x.get('benefit_check_required'):assert len(y['benefit_review'])>=100
 req=r['requirements'][x['code_id']+'|'+x['source_id']]
 assert [c['target_key'] for c in y['reference_checks']]==req
 for c in y['reference_checks']:
  assert c['view_sha256']==r['targets'][c['target_key']]['view_sha256']
  assert len(c['assessment'])>=80
 if y['status']=='retained_unchanged':
  assert y['proposed_xml'] is None and y['classification']=='retained_necessary' and imp['effects']==[]
 else:
  assert y['status']=='rewrite_draft' and y['proposed_xml']
  Markup().feed(y['proposed_xml'])
  if y.get('change_type')=='full_repeal':
   assert plain(y['proposed_xml']).startswith(('Le présent article est abrogé','Abrogé'))
   assert y['repeal_policy_id']=='editorial_direction_2026_10_19' and len(y['repeal_scope'])>=30
  if y.get('change_type')=='normative_reduction':
   assert y['reform_policy_id']=='editorial_direction_2026_10_19'
   assert y['removed_provisions'] and all(len(e)>=30 for e in y['removed_provisions'])
  for e in imp['effects']:
   assert set(e)=={'kind','measure_id','description','before','after','unit','affected_population','conditions_and_transition','replacement_or_new_burdens','source_quote','proposed_quote'}
   assert e['kind'] in kinds and e['unit'] in units
   assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
   for q,f in [('source_quote','source_xml'),('proposed_quote','proposed_xml')]:
    assert len(e[q])>=12 and e[q] in plain((x if f=='source_xml' else y)[f]),(y['number'],q,e[q])
print('24 objets ; identifiants, citations exactes, balises et références contrôlés.')
print('Statuts :',dict(Counter(x['status'] for x in a)))
print('Impacts :',dict(Counter(x['substantive_impact']['classification'] for x in a)))
print('Vérifications de renvois :',sum(len(x['reference_checks']) for x in a))
print('Mesures :',dict(Counter(e['measure_id'] for x in a for e in x['substantive_impact']['effects'])))
print('Taille answer.json :',Path('answer.json').stat().st_size)
PY"

